51	            @RequestBody BulkOpenRequest request, Claims claims, People people, ClaimStatusChanger changer,
52	            ObjectResponse<BulkOpenResponse> response) {
53	        Map<Long, Integer> personOrder = new HashMap<>();
54	        for (Person person : people.list(sheet)) {
55	            personOrder.put(person.id(), personOrder.size());
56	        }
57	        List<Claim> selected = new ArrayList<>();
58	        int refused = 0;
59	        for (Long id : new LinkedHashSet<>(request == null || request.claims() == null ? List.of() : request.claims())) {
60	            Claim claim = id == null ? null : claims.find(sheet, id);
61	            if (claim == null) {
62	                refused++;
63	            } else {
64	                selected.add(claim);
65	            }
66	        }
67	        selected.sort(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.person(), Integer.MAX_VALUE))
68	                .thenComparing(Claim::id, Comparator.reverseOrder()));
69	        int opened = 0;
70	        for (Claim claim : selected) {
71	            try {
