623	    /** Applies the change to the claim (a reject gives its reason), writing nothing when it is refused. */
624	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
625	            throws InvalidClaimStatusChangeException {
626	        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
627	            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot change status");
628	        }
629	        if (requested == ClaimStatusChange.SETTLE && claim.deferred()) {
630	            throw new InvalidClaimStatusChangeException("A deferred claim cannot be settled until its date");
631	        }
632	        // Four eyes: the user who opened a claim may not settle it, nor approve it.
633	        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
634	                && user.equals(claim.openedBy())) {
635	            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
636	        }
637	        // Only a steward approves or rejects a PENDING claim; a reject gives a reason.
638	        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
639	                && !Role.STEWARD.equals(roles.of(sheet, user))) {
640	            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
641	        }
642	        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
643	            throw new InvalidClaimStatusChangeException("A reject needs a reason");
644	        }
645	        Person person = people.find(sheet, claim.person());
646	        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit); above
647	        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
648	        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
649	                && Role.CLERK.equals(roles.of(sheet, user))) {
650	            BigDecimal limit = settings.clerkLimit(sheet);
651	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
652	                    settings.late(sheet, clock.today(sheet)));
653	            if (limit != null && due != null && due.compareTo(limit) > 0) {
654	                requested = ClaimStatusChange.PEND;
655	            }
656	        }
657	        Rollup.Snapshot before = rollup.take(sheet);
658	        ClaimStatus next = claim.status().after(requested);
659	        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
660	        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
661	            throw new InvalidClaimStatusChangeException(
662	                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
663	        }
664	        // Opening gives the sheet's next number, or, while the sheet numbers by period from on or before its today,
665	        // the next number in the claim's period (X for none); a voided claim keeps the number it had (never reused).
666	        Claim changed = claim;
667	        if (requested == ClaimStatusChange.OPEN) {
668	            LocalDate from = settings.periodNumberingFrom(sheet);
669	            if (from != null && !clock.today(sheet).isBefore(from)) {
670	                String period = periods.nameOn(sheet, LocalDate.parse(claim.date()));
671	                String key = period == null ? "" : period;
672	                changed = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
673	                claims.setPeriodNumber(sheet, claim.id(), changed.periodNumber());
674	            } else {
675	                changed = claim.withNumber(claims.nextNumber(sheet));
676	                claims.setNumber(sheet, claim.id(), changed.number());
677	            }
678	            claims.setOpenedBy(sheet, claim.id(), user);
679	        }
680	        String fields = changed.statusAuditFields(person.name());
681	        // Settling (or approving a PENDING claim, its live figure then) fixes the due at the person's grade rate in force on the claim's date (or the figure its
682	        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
683	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
684	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
685	                    settings.late(sheet, clock.today(sheet)));
686	            claims.setSettledDue(sheet, claim.id(), due);
687	            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
688	        }
689	        if (requested == ClaimStatusChange.REJECT) {
690	            fields += " reason=" + reason.trim();
691	        }
692	        log.record(sheet, user, claim.id());
693	        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
694	        rollup.record(sheet, user, before);
695	    }
