705	    DRAFT, OPEN, PENDING, SETTLED, VOID;
706	
707	    /** The status a change takes this claim to, or null when the change is not allowed from here. */
708	    public ClaimStatus after(ClaimStatusChange change) {
709	        return switch (change) {
710	            case OPEN -> this == DRAFT ? OPEN : null;
711	            case SETTLE -> this == OPEN ? SETTLED : null;
712	            case PEND -> this == OPEN ? PENDING : null;
713	            case APPROVE -> this == PENDING ? SETTLED : null;
714	            case REJECT -> this == PENDING ? OPEN : null;
715	            case VOID -> this == DRAFT || this == OPEN || this == PENDING ? VOID : null;
716	        };
717	    }
