815	/**
816	 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on the claim's date, and its today; a claim is due
817	 * by the due-by fixed when it was added. The charge is never bound by a statement: it follows the sheet's today.
818	 * It also carries the sheet's policy date, which decides how a claim's live figures round.
819	 */
820	public record Late(Dated pct, LocalDate today, LocalDate policy) {
821	
822	    /**
823	     * How the claim's live figures round: half up when it rounds on a date (its own, or for a correction the date of
824	     * the claim it corrects) before the policy date, half to even on or after it.
825	     */
826	    public RoundingMode rounding(Claim claim) {
827	        return LocalDate.parse(claim.roundsOn()).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
828	    }
829	
830	    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its due-by (fixed when it was added) before the sheet's today. */
831	    public boolean overdue(Claim claim) {
832	        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && LocalDate.parse(claim.dueBy()).isBefore(today);
833	    }
834	
835	    /**
836	     * The claim's late charge on its figure: the late percent in force on its date of the figure for every full 30 days it is overdue,
837	     * rounded in hundredths by the claim's {@link #rounding}; 0.00 when it is not overdue, and always for a correction.
838	     */
839	    public BigDecimal charge(Claim claim, BigDecimal figure) {
840	        if (figure == null || claim.correction() || !overdue(claim)) {
841	            return BigDecimal.ZERO.setScale(2);
842	        }
843	        long days = ChronoUnit.DAYS.between(LocalDate.parse(claim.dueBy()), today);
844	        return figure.multiply(pct.on(claim.date())).multiply(BigDecimal.valueOf(days / 30)).movePointLeft(2).setScale(2,
845	                rounding(claim));
846	    }
847	}
