213	 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
214	 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
215	 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
216	 * the date. Their holds are listed in the order they were added; their OPEN claims dated within a hold, unless bound
217	 * by a statement, count in no live total.
218	 */
219	public record Person(long id, String name, String grade, long version, String retiredFrom, List<Hold> holds,
220	        List<GradeFrom> grades) {
221	    /** Whether the claim, theirs, counts toward the live totals: it counts, unless it is open, not bound by a statement, and dated within one of their holds. */
222	    public boolean counts(Claim claim) {
223	        if (!claim.counts()) {
224	            return false;
225	        }
226	        if (claim.status() == ClaimStatus.SETTLED || claim.bound()) {
227	            return true;
228	        }
229	        return holds.stream().noneMatch((h) -> h.covers(claim.date()));
230	    }
231	    /** Whether a claim dated {@code date} is after this person's retirement, and so refused. */
232	    public boolean retiredBefore(LocalDate date) {
233	        return retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom));
234	    }
235	    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
236	    public String gradeOn(LocalDate date) {
237	        return gradeOn(grades, date);
238	    }
239	    /**
240	     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
241	     * bound), one at another grade, in force on its date, or one from a rate that ended (its to-date) on or before
242	     * today, the claim not being dated after today. Their due-total is n/a only when no claim does and that grade
243	     * has no rate on today.
244	     */
245	    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, Dated floor) {
246	        String then = gradeOn(claim.date());
247	        return claim.fixed()
248	                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null)
249	                || (then != null && !LocalDate.parse(claim.date()).isAfter(today)
250	                        && claim.figure(rates, then, floor) != null);
251	    }
252	    /** The grade in force on the claim's date (yyyy-mm-dd). */
253	    public String gradeOn(String date) {
254	        return gradeOn(LocalDate.parse(date));
255	    }
256	    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
257	        GradeFrom found = null;
258	        for (GradeFrom g : grades) {
259	            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
260	                continue;
261	            }
262	            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
263	                    || (found.from() == null && g.from() != null)) {
264	                found = g;
265	            }
266	        }
