873	        List<Claim> all = claims.list(sheet);
874	        Map<Long, Figures> figures = new LinkedHashMap<>();
875	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
876	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
877	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
878	        for (Person person : people.list(sheet)) {
879	            List<Claim> mine = all.stream().filter((c) -> c.person() == person.id() && person.counts(c)).toList();
880	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
881	            BigDecimal due = BigDecimal.ZERO.setScale(2);
882	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
883	            for (Claim claim : mine) {
884	                claimed = claimed.add(new BigDecimal(claim.amount()));
885	                BigDecimal d = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
886	                due = d == null ? due : due.add(d);
887	                if (d != null && late.overdue(claim)) {
888	                    overdue = overdue.add(d);
889	                }
890	            }
891	            // n/a when the grade has no rate on the sheet's today, unless a claim has a figure apart from it.
892	            boolean na = Rate.on(sheetRates, person.grade(), today) == null
893	                    && mine.stream().noneMatch((c) -> person.figureApartFrom(c, today, sheetRates, floor));
894	            due = Settings.capped(due, cap);
895	            claimedTotal = claimedTotal.add(claimed);
896	            overdueTotal = overdueTotal.add(overdue);
897	            if (!na) {
898	                dueTotal = dueTotal.add(due);
899	            }
900	            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString(),
901	                    overdue.toPlainString()));
902	        }
903	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString(),
904	                overdueTotal.toPlainString());
905	    }
