913	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
914	                    || !was.overdueTotal().equals(now.overdueTotal())) {
915	                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
916	                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
