928	/**
929	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
930	 * so tests can assert side-effects by reading that file — the second test-assertion channel
931	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
932	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
933	 *
934	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
935	 * SYNC) so a test reads the record immediately.
936	 */
937	@Service
938	public class Audit {
939	    private final Path file;
940	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
941	        this.file = Path.of(path);
942	    }
943	    /** Append one audit record. Tests assert the exact line(s) in the file. */
944	    public synchronized void record(String entry) {
945	        try {
946	            Path parent = file.toAbsolutePath().getParent();
947	            if (parent != null) {
948	                Files.createDirectories(parent);
949	            }
950	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
951	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
952	        } catch (IOException e) {
953	            throw new UncheckedIOException(e);
954	        }
955	    }
956	    /** Remove the audit file. */
957	    public synchronized void clear() {
958	        try {
959	            Files.deleteIfExists(file);
960	        } catch (IOException e) {
961	            throw new UncheckedIOException(e);
962	        }
963	    }
