2	/**
3	 * Closes the period, fixing its due-total now, and each person's on the sheet (the part of it from their claims): the due of the counted (OPEN and SETTLED, but not an unbound OPEN one dated
4	 * within its person's hold) claims dated in it (a
5	 * claim with no rate adds nothing). Refuses a period not on the sheet or already closed.
6	 */
7	public class ClosePeriod {
8	    public void close(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
9	            @RequestParam("user") String user, Periods periods, Claims claims, People people, Rates rates, Settings settings,
10	            SheetClock clock, Audit audit)
11	            throws InvalidPeriodException {
12	        Period found = periods.find(sheet, period);
13	        if (found == null) {
14	            throw new InvalidPeriodException("There is no period named " + period);
15	        }
16	        if (found.closed()) {
17	            throw new InvalidPeriodException("The period " + period + " is already closed");
18	        }
19	        LocalDate from = LocalDate.parse(found.from());
20	        LocalDate to = LocalDate.parse(found.to());
21	        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
22	        List<Rate> sheetRates = rates.list(sheet);
23	        Dated floor = settings.floor(sheet);
24	        Late late = settings.late(sheet, clock.today(sheet));
25	        BigDecimal total = BigDecimal.ZERO.setScale(2);
26	        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
27	        byId.keySet().forEach((id) -> perPerson.put(id, BigDecimal.ZERO.setScale(2)));
28	        for (Claim claim : claims.list(sheet)) {
29	            LocalDate date = LocalDate.parse(claim.date());
30	            Person person = byId.get(claim.person());
31	            if (person == null || !person.counts(claim) || date.isBefore(from) || date.isAfter(to)) {
32	                continue;
33	            }
34	            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
35	            if (due != null) {
36	                total = total.add(due);
37	                perPerson.merge(person.id(), due, BigDecimal::add);
38	            }
39	        }
40	        if (!periods.close(sheet, period, total, perPerson)) {
41	            throw new InvalidPeriodException("The period " + period + " is already closed");
42	        }
43	        audit.record("PERIOD_CLOSED sheet=" + sheet + " by=" + user + " period=" + period + " total="
44	                + total.toPlainString());
45	    }
46	}
