282	/**
283	 * Takes a statement of the person: records their due-total now (late charges included), binds each of their
284	 * counting claims to the figure it has now (without its late charge) and unbinds the rest. The due-total is n/a
285	 * when their grade has no rate on the sheet's today, unless a
286	 * counting claim has a figure apart from it (settled, bound, or at another grade in force on its date): then it is the figures there are.
287	 */
288	public class TakeStatement {
289	    public void take(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
290	            Claims claims, Rates rates, Statements statements, SheetClock clock, Settings settings, Audit audit,
291	            Rollup rollup) {
292	        Rollup.Snapshot before = rollup.take(sheet);
293	        LocalDate today = clock.today(sheet);
294	        List<Rate> sheetRates = rates.list(sheet);
295	        Dated floor = settings.floor(sheet);
296	        Late late = settings.late(sheet, today);
297	        List<Claim> mine = claims.list(sheet).stream().filter((c) -> c.person() == person.id()).toList();
298	        boolean na = Rate.on(sheetRates, person.grade(), today) == null
299	                && mine.stream().noneMatch((c) -> person.counts(c) && person.figureApartFrom(c, today, sheetRates, floor));
300	        BigDecimal total = BigDecimal.ZERO.setScale(2);
301	        int count = 0;
302	        for (Claim claim : mine) {
303	            if (person.counts(claim)) {
304	                // The statement binds the figure; the late charge keeps following the sheet's today.
305	                claims.setStated(sheet, claim.id(), true, claim.figure(sheetRates, person.gradeOn(claim.date()), floor, late.rounding(claim)));
306	                BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
307	                total = due == null ? total : total.add(due);
308	                count++;
309	            } else if (claim.stated()) {
310	                claims.setStated(sheet, claim.id(), false, null);
311	            }
312	        }
313	        BigDecimal dueTotal = na ? null : Settings.capped(total, settings.cap(sheet));
314	        statements.add(sheet, person.id(), dueTotal, today);
315	        audit.record("STATEMENT sheet=" + sheet + " by=" + user + " name=" + person.name() + " due-total="
316	                + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
317	        rollup.record(sheet, user, before);
318	    }
319	}
