503	/**
504	 * Checks every pasted line (name,amount,date,note; the note may hold commas, the date may be blank for the sheet's
505	 * today, the note may be absent) by the claim form's rules before anything is written, so a refused paste adds
506	 * nothing. The name must be on the sheet (ignoring case). A paste carries no corrected number, so a negative amount
507	 * is refused as on the form without one. Blank lines are skipped; a paste with no line is refused.
508	 */
509	public class ValidatePaste {
510	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
511	    public void validate(@PathVariable("sheet") String sheet, @RequestBody PasteRequest request, People people,
512	            SheetClock clock, Periods periods, Out<PastedClaims> pasted) throws InvalidClaimException {
513	        String text = request == null || request.text() == null ? "" : request.text();
514	        List<PastedClaim> lines = new ArrayList<>();
515	        int at = 0;
516	        for (String line : text.split("\\r?\\n")) {
517	            at++;
518	            if (line.isBlank()) {
519	                continue;
520	            }
521	            lines.add(check(sheet, at, line, people, clock, periods));
522	        }
523	        if (lines.isEmpty()) {
524	            throw new InvalidClaimException("Paste at least one line of name,amount,date,note");
525	        }
526	        pasted.set(new PastedClaims(lines));
527	    }
528	    private static PastedClaim check(String sheet, int at, String line, People people, SheetClock clock,
529	            Periods periods) throws InvalidClaimException {
530	        String[] fields = line.split(",", 4);
531	        String name = fields[0].trim();
532	        String amount = fields.length > 1 ? fields[1].trim() : "";
533	        String date = fields.length > 2 ? fields[2].trim() : "";
534	        String note = fields.length > 3 ? fields[3].trim() : "";
535	        Person person = name.isEmpty() ? null : people.findByName(sheet, name);
536	        if (person == null) {
537	            throw new InvalidClaimException("Line " + at + ": no one named " + name + " is on the sheet");
538	        }
539	        if (!AMOUNT.matcher(amount).matches()) {
540	            throw new InvalidClaimException("Line " + at + ": the amount must be a number with up to two decimals");
541	        }
542	        BigDecimal value = new BigDecimal(amount);
543	        if (value.signum() < 0) {
544	            throw new InvalidClaimException("Line " + at + ": a negative amount must name the claim it corrects");
545	        }
546	        LocalDate on;
547	        try {
548	            on = date.isEmpty() ? clock.today(sheet) : LocalDate.parse(date);
549	        } catch (DateTimeParseException e) {
550	            throw new InvalidClaimException("Line " + at + ": not a valid date: " + date);
551	        }
552	        if (periods.closedOn(sheet, on)) {
553	            throw new InvalidClaimException("Line " + at + ": a claim may not be dated inside a closed period");
554	        }
555	        if (person.retiredBefore(on)) {
556	            throw new InvalidClaimException(
557	                    "Line " + at + ": a claim may not be dated after the person's retirement date");
558	        }
559	        return new PastedClaim(person, new ClaimInput(value, on, note));
560	    }
561	}
