49	/** An amount times a percent, divided by 100, in hundredths rounded half to even (1.025 -> 1.02,
50	 *  1.035 -> 1.04), or half up when `halfUp` (1.025 -> 1.03); undefined when there is no rate. Worked in whole
51	 *  numbers so no float error shows. */
52	export function dueCents(amount: string, pct: string | undefined, halfUp = false): bigint | undefined {
53	  if (pct === undefined) return undefined;
54	  const product = hundredths(amount) * hundredths(pct);
55	  // Rounded on the magnitude, so a negative amount (a correction) rounds as its positive would.
56	  const abs = product < 0n ? -product : product;
57	  let quotient = abs / 10000n;
58	  const remainder = abs % 10000n;
59	  if (remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n))) quotient += 1n;
60	  return product < 0n ? -quotient : quotient;
61	}
