71	/** The sheet's settings: the clerk limit with two decimals, the most due a clerk may settle ('' for no limit);
72	 *  the floor with two decimals, the least a claim's live due is; and the terms, the whole days after its date by
73	 *  which a claim is due; and the late percent with two decimals, charged on an overdue claim's figure for every
74	 *  full 30 days it is overdue; and the policy date (yyyy-MM-dd; '' for the sheet's today): a claim dated before it
75	 *  rounds half up, on or after it half to even; and the period numbering from-date (yyyy-MM-dd; '' for off): while
76	 *  the sheet's today is on or after it, a claim opened is numbered within its period; and each grade's own terms
77	 *  (whole days; '' when it takes the sheet's terms), from which a claim's due-by is fixed when it is added; and the
78	 *  cap with two decimals, the most a person's due-total is ('' for no cap). Each is the value in force on the sheet's
79	 *  today. And, for each dated key (every one that carries a figure), its values as recorded, by from-date. */
80	export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string;
