94	/** The figure in force on a date: the value of the latest from-date on or before it, before every from-date (or
95	 *  where a blank is in force) the starting value. */
96	function datedCents(values: DatedValue[] | undefined, start: string): DatedCents {
97	  const sorted = [...(values ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
98	  return (date) => {
99	    let value = start;
100	    for (const v of sorted) {
101	      if (v.from > date) break;
102	      value = v.value === '' ? start : v.value;
103	    }
104	    return hundredths(value);
105	  };
