/** A whole number of hundredths as a two-decimal string. */
export function twoDecimals(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
}

/** An amount times a percent, divided by 100, in hundredths rounded half to even (1.025 -> 1.02,
 *  1.035 -> 1.04), or half up when `halfUp` (1.025 -> 1.03); undefined when there is no rate. Worked in whole
 *  numbers so no float error shows. */
export function dueCents(amount: string, pct: string | undefined, halfUp = false): bigint | undefined {
  if (pct === undefined) return undefined;
  const product = hundredths(amount) * hundredths(pct);
  // Rounded on the magnitude, so a negative amount (a correction) rounds as its positive would.
  const abs = product < 0n ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n))) quotient += 1n;
  return product < 0n ? -quotient : quotient;
}

/** A due as the screen shows it: two decimals, or n/a when there is no rate. */
export function showDue(cents: bigint | undefined): string {
  return cents === undefined ? 'n/a' : twoDecimals(cents);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { hundredths } from '../rates/rates';

/** The sheet's settings: the clerk limit with two decimals, the most due a clerk may settle ('' for no limit);
 *  the floor with two decimals, the least a claim's live due is; and the terms, the whole days after its date by
 *  which a claim is due; and the late percent with two decimals, charged on an overdue claim's figure for every
 *  full 30 days it is overdue; and the policy date (yyyy-MM-dd; '' for the sheet's today): a claim dated before it
 *  rounds half up, on or after it half to even; and the period numbering from-date (yyyy-MM-dd; '' for off): while
 *  the sheet's today is on or after it, a claim opened is numbered within its period; and each grade's own terms
 *  (whole days; '' when it takes the sheet's terms), from which a claim's due-by is fixed when it is added; and the
 *  cap with two decimals, the most a person's due-total is ('' for no cap). Each is the value in force on the sheet's
 *  today. And, for each dated key (every one that carries a figure), its values as recorded, by from-date. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string;
  termsA: string; termsB: string; termsC: string; cap: string; dated: Partial<Record<SettingKey, DatedValue[]>> };

/** A dated setting's value as recorded: in force from its from-date (yyyy-MM-dd). */
export type DatedValue = { from: string; value: string };

/** A figure in force by date (yyyy-MM-dd), in hundredths. */
export type DatedCents = (date: string) => bigint;

/** Whether a setting is dated: every one that carries a figure is; the policy and period numbering dates are not. */
export function isDated(key: SettingKey): boolean {
  return key !== 'policy-date' && key !== 'period-numbering-from';
}

/** The figure in force on a date: the value of the latest from-date on or before it, before every from-date (or
 *  where a blank is in force) the starting value. */
function datedCents(values: DatedValue[] | undefined, start: string): DatedCents {
  const sorted = [...(values ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  return (date) => {
    let value = start;
    for (const v of sorted) {
      if (v.from > date) break;
      value = v.value === '' ? start : v.value;
    }
    return hundredths(value);
  };
}

/** A setting's key as the server names it, with the field of {@link Settings} that shows it. */
export type SettingKey = 'clerk-limit' | 'floor' | 'terms' | 'late-pct' | 'policy-date' | 'period-numbering-from'
  | 'terms-A' | 'terms-B' | 'terms-C' | 'cap';

/** The grades that may have terms of their own, with the setting key and field of {@link Settings} of each. */
export const GRADE_TERMS = [
  { grade: 'A', key: 'terms-A', field: 'termsA' },
  { grade: 'B', key: 'terms-B', field: 'termsB' },
  { grade: 'C', key: 'terms-C', field: 'termsC' },
] as const;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The terms a sheet starts with. */
export const DEFAULT_TERMS = '14';

export const settingsKey = (sheet: string) => ['settings', sheet] as const;

export const settingsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/settings`;

export function useSettings(sheet: string) {
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(settingsPath(sheet)),
  });
}

/** The sheet's floor in hundredths by date: the least a claim's live due is, the one in force on its date. */
export function useFloorCents(sheet: string): DatedCents {
  const { data } = useSettings(sheet);
  return datedCents(data?.dated?.floor, DEFAULT_FLOOR);
}

/** The sheet's cap in hundredths: the most a person's due-total is; undefined when there is none. */
export function useCapCents(sheet: string): bigint | undefined {
  const { data } = useSettings(sheet);
  return data?.cap ? hundredths(data.cap) : undefined;
}

/** The sheet's late percent in hundredths by date: charged on an overdue claim's figure for every full 30 days it is
 *  overdue, the one in force on the claim's date. */
export function useLatePctCents(sheet: string): DatedCents {
  const { data } = useSettings(sheet);
  return datedCents(data?.dated?.['late-pct'], DEFAULT_LATE_PCT);
}

/** The sheet's policy date (yyyy-MM-dd), or '' when it is the sheet's today. */
export function usePolicyDate(sheet: string): string {
  const { data } = useSettings(sheet);
  return data?.policyDate ?? '';
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { gradeOn, peoplePath, usePeople } from '../people/people';
import type { Grade, Person } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import { rateOf, showDue, twoDecimals, useRates } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { periodOf, usePeriods } from '../periods/periods';
import { useCapCents, useFloorCents } from '../settings/settings';
import {
  claimDueCents,
  claimed,
  claimsKey,
  claimsPath,
  counted,
  overdue,
  overdueCents,
  personDueCents,
  uncappedPersonDueCents,
  useClaims,
  useLate,
} from './claims';
import type { Claim, ClaimStatusChange } from './claims';
import { selectClaim, useSelectedClaims } from './selection';

type Draft = { amount: string; date: string; note: string; corrects: string };
const EMPTY: Draft = { amount: '', date: '', note: '', corrects: '' };

function ClaimedHeader() {
  return (
    <>
      <th>Claimed</th>
      <th>Due total</th>
      <th>Excess</th>
      <th>Overdue</th>
      <th>Overdue total</th>
      <th>Claims</th>
    </>
  );
}

const CHANGES: { change: ClaimStatusChange; label: string }[] = [
  { change: 'open', label: 'Open' },
  { change: 'settle', label: 'Settle' },
  { change: 'void', label: 'Void' },
  { change: 'approve', label: 'Approve' },
];

// One claim with its status and the buttons that change it. Every button is offered; the server
// refuses a change the claim's status does not allow, and the row shows that error until its next action.
function ClaimRow({ sheet, user, claim, rates, grade, editing, onEdit, onCancel }: {
  sheet: string;
  user: string;
  claim: Claim;
  rates: Rate[];
  grade: Grade | undefined;
  editing: boolean;
  onEdit: () => void;
  onCancel: () => void;
}) {
  const queryClient = useQueryClient();
  const { data: periods = [] } = usePeriods(sheet);
  const floor = useFloorCents(sheet);
  const today = useSheetToday(sheet);
  const late = useLate(sheet);
  const status = useMutation({
    mutationFn: (change: ClaimStatusChange) =>
      postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/${change}`, user), change === 'reject' ? { reason } : {}),
    onSuccess: (updated) => queryClient.setQueryData(claimsKey(sheet), updated),
  });

  const act = useSubmitOnce(status);
  // A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet, picked beside the Reassign button.
  const { data: people = [] } = usePeople(sheet);
  const [moveTo, setMoveTo] = useState('');
  const move = useMutation({
    mutationFn: (to: number) =>
      postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/reassign`, user), { to }),
    onSuccess: (updated) => {
      setMoveTo('');
      queryClient.setQueryData(claimsKey(sheet), updated);
    },
  });
  const reassign = useSubmitOnce(move);
  // A steward re-settles a SETTLED claim: its due is fixed again at today's live figure.
  const resettleMutation = useMutation({
    mutationFn: () => postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/resettle`, user), {}),
    onSuccess: (updated) => queryClient.setQueryData(claimsKey(sheet), updated),
  });
  const resettle = useSubmitOnce(resettleMutation);
  // An OPEN claim is deferred to a date after the sheet's today, typed beside the Defer button.
  const [deferTo, setDeferTo] = useState('');
  const deferMutation = useMutation({
    mutationFn: (until: string) => postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/defer`, user), { until }),
    onSuccess: (updated) => {
      setDeferTo('');
      queryClient.setQueryData(claimsKey(sheet), updated);
    },
  });
  const defer = useSubmitOnce(deferMutation);
  const selected = useSelectedClaims(sheet).has(claim.id);
  // Only a draft can be edited: Edit on any other claim shows the row's error instead of the editor.
  const [editRefused, setEditRefused] = useState(false);
  // A steward rejects a PENDING claim with a reason, typed beside the Reject button.
  const [reason, setReason] = useState('');

  return (
    <li data-testid={`claim-row-${claim.id}`}>
      <input
        type="checkbox"
        data-testid="claim-select"
        checked={selected}
        onChange={(e) => selectClaim(sheet, claim.id, e.target.checked)}
      />{' '}
      <span data-testid="claim-amount">{claim.amount}</span>{' '}
      <span data-testid="claim-date">{claim.date}</span>{' '}
      <span data-testid="claim-note">{claim.note}</span>{' '}
      due <span data-testid="claim-due">{showDue(claimDueCents(claim, rateOf(rates, grade, claim.date), floor, late))}</span>{' '}
      due by <span data-testid="claim-due-by">{claim.dueBy}</span>{' '}
      overdue <span data-testid="claim-overdue">{overdue(claim, today) ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-status">{claim.status}</span>{' '}
      stated <span data-testid="claim-stated">{claim.stated ? 'yes' : 'no'}</span>{' '}
      period <span data-testid="claim-period">{periodOf(periods, claim.date)?.name ?? ''}</span>{' '}
      {(claim.periodNumber ?? claim.number) !== null && '#'}
      <span data-testid="claim-number">{claim.periodNumber ?? claim.number ?? ''}</span>{' '}
      {claim.openedBy !== null && 'opened by '}
      <span data-testid="claim-opened-by">{claim.openedBy ?? ''}</span>{' '}
      {claim.corrects !== null && 'corrects #'}
      <span data-testid="claim-corrects">{claim.corrects ?? ''}</span>{' '}
      deferred <span data-testid="claim-deferred">{claim.deferred ? 'yes' : 'no'}</span>{' '}
      {claim.deferred && 'until '}
      <span data-testid="claim-deferred-until">{claim.deferred ? claim.deferredUntil : ''}</span>{' '}
      {CHANGES.map(({ change, label }) => (
        <button
          key={change}
          type="button"
          data-testid={`claim-${change}`}
          disabled={status.isPending}
          onClick={() => {
            setEditRefused(false);
            move.reset();
            resettleMutation.reset();
            deferMutation.reset();
            act(change);
          }}
        >
          {label}
        </button>
      ))}{' '}
      <input
        data-testid="claim-reject-reason"
        placeholder="reject reason"
        value={reason}
        onChange={(e) => {
          setReason(e.target.value);
          status.reset();
          move.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="claim-reject"
        disabled={status.isPending}
        onClick={() => {
          setEditRefused(false);
          move.reset();
          resettleMutation.reset();
          deferMutation.reset();
          act('reject');
        }}
      >
        Reject
      </button>{' '}
      <button
        type="button"
        data-testid="claim-edit"
        onClick={() => {
          status.reset();
          move.reset();
          resettleMutation.reset();
          deferMutation.reset();
          if (claim.status !== 'DRAFT') {
            setEditRefused(true);
            return;
          }
          setEditRefused(false);
          onEdit();
        }}
      >
        Edit
      </button>
      <select
        data-testid="claim-reassign-to"
        value={moveTo}
        onChange={(e) => {
          setMoveTo(e.target.value);
          move.reset();
        }}
      >
        <option value="">move to…</option>
        {people
          .filter((p) => p.id !== claim.person)
          .map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
      </select>{' '}
      <button
        type="button"
        data-testid="claim-reassign"
        disabled={move.isPending || moveTo === ''}
        onClick={() => {
          setEditRefused(false);
          status.reset();
          resettleMutation.reset();
          deferMutation.reset();
          reassign(Number(moveTo));
        }}
      >
        Reassign
      </button>{' '}
      <button
        type="button"
        data-testid="claim-resettle"
        disabled={resettleMutation.isPending}
        onClick={() => {
          setEditRefused(false);
          status.reset();
          move.reset();
          deferMutation.reset();
          resettle(undefined);
        }}
      >
        Re-settle
      </button>{' '}
      <input
        data-testid="claim-defer-date"
        placeholder="defer until yyyy-mm-dd"
        value={deferTo}
        onChange={(e) => {
          setDeferTo(e.target.value);
          deferMutation.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="claim-defer"
        disabled={deferMutation.isPending}
        onClick={() => {
          setEditRefused(false);
          status.reset();
          move.reset();
          resettleMutation.reset();
          defer(deferTo);
        }}
      >
        Defer
      </button>{' '}
      {editing && (
        <button type="button" data-testid="claim-cancel" onClick={onCancel}>
          Cancel
        </button>
      )}
      <ol>
        {claim.log.map((line, i) => (
          <li key={i} data-testid="claim-log-line">
            {line.status} by {line.by} on {line.on} due={line.due}
          </li>
        ))}
      </ol>
      {editRefused && (
        <span data-testid="claim-error" role="alert">
          {' '}A {claim.status} claim cannot be edited; only a DRAFT can (void it and add a new one).
        </span>
      )}
      {status.isError && (
        <span data-testid="claim-error" role="alert">
          {' '}A {claim.status} claim cannot be changed that way (the user who opened it cannot settle or approve it; only a steward approves or rejects a PENDING claim, and a reject needs a reason).
        </span>
      )}
      {resettleMutation.isError && (
        <span data-testid="claim-error" role="alert">
          {' '}A {claim.status} claim cannot be re-settled (only a steward re-settles, and only a SETTLED claim outside a closed period).
        </span>
      )}
      {deferMutation.isError && (
        <span data-testid="claim-error" role="alert">
          {' '}A {claim.status} claim cannot be deferred (only an OPEN claim outside a closed period, and only to a date after the sheet's today).
        </span>
      )}
      {move.isError && (
        <span data-testid="claim-error" role="alert">
          {' '}A {claim.status} claim cannot be reassigned (only a steward moves a claim, and only a DRAFT, OPEN or PENDING one, to another person).
        </span>
      )}
    </li>
  );
}

// A person's claimed total, then their claims (newest first) under one form that adds a claim or,
// once a claim's editor is opened, edits it. A blank date takes the sheet's today on the server.
function PersonClaims({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: all = [] } = useClaims(sheet);
  const claims = all.filter((c) => c.person === person.id);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloorCents(sheet);
  const cap = useCapCents(sheet);
  const today = useSheetToday(sheet);
  const late = useLate(sheet);
  // The excess: how far the sum of their figures is above the cap (0.00 when it is not, or is n/a).
  const uncapped = uncappedPersonDueCents(claims, rates, person, today, floor, late);
  const excess = uncapped !== undefined && cap !== undefined && uncapped > cap ? uncapped - cap : 0n;
  const lateClaims = overdueCents(claims, [person], rates, late, floor);
  const [draft, setDraft] = useState<Draft>(EMPTY);
  const [editing, setEditing] = useState<number | null>(null);

  const save = useMutation({
    mutationFn: ({ id, body }: { id: number | null; body: Draft }) =>
      id === null
        ? postJson<Claim[]>(byUser(`${peoplePath(sheet)}/${person.id}/claims`, user), body)
        : putJson<Claim[]>(byUser(`${claimsPath(sheet)}/${id}`, user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(claimsKey(sheet), updated);
      setDraft(EMPTY);
      setEditing(null);
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const open = (c: Claim) => {
    setEditing(c.id);
    setDraft({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects === null ? '' : String(c.corrects) });
    save.reset();
  };

  const cancel = () => {
    setEditing(null);
    setDraft(EMPTY);
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses an amount that is not a number with up to two decimals, a bad date, or a negative amount
    // (a correction) that does not name a SETTLED claim of this person by number.
    send({ id: editing, body: draft });
  };

  return (
    <>
      <td data-testid="person-claimed">{claimed(counted(claims, [person]))}</td>
      <td data-testid="person-due-total">{showDue(personDueCents(claims, rates, person, today, floor, late, cap))}</td>
      <td data-testid="person-excess">{twoDecimals(excess)}</td>
      <td data-testid="person-overdue-count">{lateClaims.count}</td>
      <td data-testid="person-overdue-total">{twoDecimals(lateClaims.cents)}</td>
      <td>
        <form onSubmit={submit}>
          <input
            data-testid="claim-form-amount"
            placeholder="amount"
            value={draft.amount}
            onChange={(e) => change({ amount: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-date"
            placeholder="yyyy-mm-dd"
            value={draft.date}
            onChange={(e) => change({ date: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-note"
            placeholder="note"
            value={draft.note}
            onChange={(e) => change({ note: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-corrects"
            placeholder="corrects #"
            value={draft.corrects}
            onChange={(e) => change({ corrects: e.target.value })}
          />{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing === null ? 'Add claim' : 'Save claim'}
          </button>
          {save.isError && (
            <span data-testid="claim-form-error" role="alert">
              {' '}A claim needs an amount with up to two decimals, and a valid date not after the person's retirement date; a negative amount is a correction and must name, by number, a SETTLED claim of this person; only a DRAFT claim can be edited.
            </span>
          )}
        </form>
        <ul>
          {claims.map((c) => (
            <ClaimRow
              key={c.id}
              sheet={sheet}
              user={user}
              claim={c}
              rates={rates}
              grade={gradeOn(person, c.date)}
              editing={editing === c.id}
              onEdit={() => open(c)}
              onCancel={cancel}
            />
          ))}
        </ul>
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 10, Component: ClaimedHeader }),
  PersonColumns.fill({ order: 10, Component: PersonClaims }),
];
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { GRADES, isRetired, peopleKey, peoplePath, usePeople, useShowRetired } from './people';
import type { Grade, Person } from './people';
import { claimsKey } from '../claims/claims';
import type { Claim } from '../claims/claims';

// gradeFrom is the date an edit records the grade from (yyyy-mm-dd; blank for the sheet's today); a person's
// first grade applies from the beginning of time.
type Draft = { name: string; grade: Grade; gradeFrom: string };
const EMPTY: Draft = { name: '', grade: 'A', gradeFrom: '' };

type Quick = { name: string; amount: string };
const QUICK_EMPTY: Quick = { name: '', amount: '' };

// The quick-add bar: a name and an amount make a draft claim dated the sheet's today with an empty
// note, for the person of that name (ignoring case), who is first added with grade A when not on the
// sheet. The server checks every rule before writing, so a refusal adds no one.
function QuickAdd({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const [draft, setDraft] = useState<Quick>(QUICK_EMPTY);

  const add = useMutation({
    mutationFn: (body: Quick) =>
      postJson<{ people: Person[]; claims: Claim[] }>(
        byUser(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, user),
        body,
      ),
    onSuccess: (updated) => {
      queryClient.setQueryData(peopleKey(sheet), updated.people);
      queryClient.setQueryData(claimsKey(sheet), updated.claims);
      setDraft(QUICK_EMPTY);
    },
  });
  const send = useSubmitOnce(add);

  const change = (next: Partial<Quick>) => {
    setDraft((d) => ({ ...d, ...next }));
    add.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    send(draft);
  };

  return (
    <form onSubmit={submit}>
      <label>
        Quick add: name{' '}
        <input data-testid="quick-name" value={draft.name} onChange={(e) => change({ name: e.target.value })} />
      </label>{' '}
      <label>
        Amount{' '}
        <input data-testid="quick-amount" value={draft.amount} onChange={(e) => change({ amount: e.target.value })} />
      </label>{' '}
      <button type="submit" data-testid="quick-submit" disabled={add.isPending}>
        Add claim
      </button>
      {add.isError && (
        <span data-testid="quick-error" role="alert">
          {' '}
          A quick add needs a name and an amount of 0.00 or more with up to two decimals, dated outside any closed
          period.
        </span>
      )}
    </form>
  );
}

// The sheet's people: listed in the order they were added (retired ones only when shown), with one form that adds a person or,
// once a person's editor is opened, edits them. The editor remembers the version of the person it loaded;
// when someone else has saved them since, the save is refused and the form shows their current values.
function People({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: everyone = [] } = usePeople(sheet);
  const [showRetired, setShowRetired] = useShowRetired();
  // Retired people have no row at all unless "show retired" is on; their claims still count in every total.
  const people = showRetired ? everyone : everyone.filter((p) => !isRetired(p));
  const [draft, setDraft] = useState<Draft>(EMPTY);
  const [editing, setEditing] = useState<{ id: number; version: number } | null>(null);

  const save = useMutation({
    mutationFn: ({ edit, body }: { edit: { id: number; version: number } | null; body: Draft }) =>
      edit === null
        ? postJson<Person[]>(byUser(peoplePath(sheet), user), body)
        : putJson<Person[]>(byUser(`${peoplePath(sheet)}/${edit.id}`, user), { ...body, version: edit.version }),
    onSuccess: (updated) => {
      queryClient.setQueryData(peopleKey(sheet), updated);
      setDraft(EMPTY);
      setEditing(null);
    },
    onError: async (error, { edit }) => {
      if (edit === null || !(error instanceof HttpError) || error.status !== 412) return;
      // Someone else saved the person: show what is stored now, and edit from that version.
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      const p = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((c) => c.id === edit.id);
      if (p) {
        setDraft({ name: p.name, grade: p.grade, gradeFrom: '' });
        setEditing({ id: p.id, version: p.version });
      }
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const open = (p: Person) => {
    setEditing({ id: p.id, version: p.version });
    setDraft({ name: p.name, grade: p.grade, gradeFrom: '' });
    save.reset();
  };

  const cancel = () => {
    setEditing(null);
    setDraft(EMPTY);
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses an empty name, one already on the sheet, or a save over someone else's;
    // its refusal shows as the form's error.
    send({ edit: editing, body: draft });
  };

  return (
    <section>
      <h2>People</h2>
      <form onSubmit={submit}>
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={draft.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={draft.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-grade-from"
            placeholder="yyyy-mm-dd"
            value={draft.gradeFrom}
            onChange={(e) => change({ gradeFrom: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && (
          <span data-testid="person-form-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.status === 412
              ? 'Someone else saved this person since you opened it; the form now shows their values.'
              : 'A person needs a name not already on the sheet, a grade of A, B or C, and a from-date that is a valid date or blank.'}
          </span>
        )}
      </form>
      <QuickAdd sheet={sheet} user={user} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PersonColumnHeaders.Slot sheet={sheet} user={user} />
            <th />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonColumns.Slot sheet={sheet} user={user} person={p} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 10, Component: People });
